"use strict";(globalThis.webpackChunkgrc||=[]).push([[89576],{73281(e){e.exports=JSON.parse('{"citeKey":"sun1998performancerangerestructuring","slug":"sun-1998-performance-range-311f","title":"Performance Range Comparison for Restructuring Compilation","authors":["X.-H. Sun","M. Pantano","T. Fahringer"],"venue":"The International Conference on Parallel Processing","type":"Conference","entryType":"inproceedings","date":"August, 1998","year":1998,"era":"archive","month":8,"doi":"10.1109/icpp.1998.708534","abstract":"A major difficulty in restructuring compilation is how to compare parallel performance over a range of system and problem sizes. This study introduces the concept of range comparison for data-parallel program- ming. Unlike conventional execution time comparison in which performance is compared for a particular sys- tem and problem size, range comparison compares the performance of programs over a range of ensemble and problem sizes via scalability and performance crossing point analysis. An algorithm is developed to predict the crossing point automatically. The correctness of the algorithm is proved and a methodology is developed to integrate range comparison into restructuring compi- lations. A preliminary prototype of the methodology is implemented and tested under Vienna Fortran Compi- lation System. Experimental results demonstrate that range comparison is feasible and effective.","hasAbstract":true,"lede":"A major difficulty in restructuring compilation is how to compare parallel performance over a range of system and problem sizes.","links":{"pdf":"https://grc.iit.edu/papers/1998/sun-1998-performance-range-311f.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);